    ('2608-04026', 1, '@inproceedings{lessardDirectSynthesisIterative2020,\n  title = {Direct Synthesis of Iterative Algorithms with Bounds on Achievable Worst-Case Convergence Rate},\n  booktitle = {2020 {{American Control Conference}}},\n  author = {Lessard, Laurent and Seiler, Peter},\n  year = 2020,\n  pages = {119--125},\n  address = {Denver},\n  timestamp = {2026-02-17T00:37:25Z},\n  file = {Snapshot:R\\:\\\\Zotero\\\\storage\\\\76XAI6B3\\\\9147401.html:text/html}\n}', 1, '@inproceedings{lessardDirectSynthesisIterative2020a,\n  title = {Direct Synthesis of Iterative Algorithms with Bounds on Achievable Worst-Case Convergence Rate},\n  booktitle = {2020 {{American Control Conference}} ({{ACC}})},\n  author = {Lessard, Laurent and Seiler, Peter},\n  year = 2020,\n  month = jul,\n  pages = {119--125},\n  address = {Denver, CO},\n  issn = {2378-5861},\n  doi = {10.23919/ACC45564.2020.9147401},\n  urldate = {2024-09-15},\n  abstract = {Iterative first-order methods such as gradient descent and its variants are widely used for solving optimization and machine learning problems. There has been recent interest in analytic or numerically efficient methods for computing worst-case performance bounds for such algorithms, for example over the class of strongly convex loss functions. A popular approach is to assume the algorithm has a fixed size (fixed dimension, or memory) and that its structure is parameterized by one or two hyper-parameters, for example a learning rate and a momentum parameter. Then, a Lyapunov function is sought to certify robust stability and subsequent optimization can be performed to find optimal hyperparameter tunings. In the present work, we instead fix the constraints that characterize the loss function and apply techniques from robust control synthesis to directly search over algorithms. This approach yields stronger results than those previously available, since the bounds produced hold over algorithms with an arbitrary, but finite, amount of memory rather than just holding for algorithms with a prescribed structure.},\n  keywords = {Convergence,Iterative methods,Linear matrix inequalities,Optimization,Radio frequency,Robust control,Symmetric matrices},\n  timestamp = {2026-02-17T00:37:25Z},\n  file = {IEEE Xplore Full Text PDF:R\\:\\\\Zotero\\\\storage\\\\J27GMW8W\\\\Lessard and Seiler - 2020 - Direct Synthesis of Iterative Algorithms With Boun.pdf:application/pdf;IEEE Xplore Abstract Record:R\\:\\\\Zotero\\\\storage\\\\6PGYX6YS\\\\9147401.html:text/html}\n}', True),
