    ('2608-08428', 1, '@article{Calabrese:2009qy,\n    author = "Calabrese, Pasquale and Cardy, John",\n    title = "{Entanglement entropy and conformal field theory}",\n    eprint = "0905.4013",\n    archivePrefix = "arXiv",\n    primaryClass = "cond-mat.stat-mech",\n    doi = "10.1088/1751-8113/42/50/504005",\n    journal = "J. Phys. A",\n    volume = "42",\n    pages = "504005",\n    year = "2009"\n}', 1, '@article{Calabrese:2004eu,\n    author = "Calabrese, Pasquale and Cardy, John L.",\n    title = "{Entanglement entropy and quantum field theory}",\n    eprint = "hep-th/0405152",\n    archivePrefix = "arXiv",\n    doi = "10.1088/1742-5468/2004/06/P06002",\n    journal = "J. Stat. Mech.",\n    volume = "0406",\n    pages = "P06002",\n    year = "2004"\n}', False),
    ('2608-04166', 1, "@article{aseeri_influence_2021,\n\ttitle = {The {Influence} of {Avatar} {Representation} on {Interpersonal} {Communication} in {Virtual} {Social} {Environments}},\n\tvolume = {27},\n\tissn = {1941-0506},\n\tdoi = {10.1109/TVCG.2021.3067783},\n\tabstract = {Current avatar representations used in immersive VR applications lack features that may be important for supporting natural behaviors and effective communication among individuals. This study investigates the impact of the visual and nonverbal cues afforded by three different types of avatar representations in the context of several cooperative tasks. The avatar types we compared are No\\_Avatar (HMD and controllers only), Scanned\\_Avatar (wearing an HMD), and Heal\\_Avatar (video-see-through). The subjective and objective measures we used to assess the quality of interpersonal communication include surveys of social presence, interpersonal trust, communication satisfaction, and attention to behavioral cues, plus two behavioral measures: duration of mutual gaze and number of unique words spoken. We found that participants reported higher levels of trustworthiness in the Real\\_Avatar condition compared to the Scanned\\_Avatar and No\\_Avatar conditions. They also reported a greater level of attentional focus on facial expressions compared to the No\\_Avatar condition and spent more extended time, for some tasks, attempting to engage in mutual gaze behavior compared to the Scanned\\_Avatar and No\\_Avatar conditions. In both the Heal\\_Avatar and Scanned\\_Avatar conditions, participants reported higher levels of co-presence compared with the No\\_Avatar condition. In the Scanned\\_Avatar condition, compared with the Heal\\_Avatar and No\\_Avatar conditions, participants reported higher levels of attention to body posture. Overall, our exit survey revealed that a majority of participants (66.67\\%) reported a preference for the Real\\_Avatar, compared with 25.00\\% for the Scanned\\_Avatar and 8.33\\% for the No\\_Avatar, These findings provide novel insight into how a user's experience in a social VR scenario is affected by the type of avatar representation provided.},\n\tnumber = {5},\n\tjournal = {IEEE Transactions on Visualization and Computer Graphics},\n\tauthor = {Aseeri, Sahar and Interrante, Victoria},\n\tmonth = may,\n\tyear = {2021},\n\tnote = {Conference Name: IEEE Transactions on Visualization and Computer Graphics},\n\tkeywords = {Task analysis, trust, Avatars, Three-dimensional displays, Virtual environments, Atmospheric measurements, behavioral cues, communication satisfaction, interpersonal communication, Particle measurements, Resists, social presence, virtual environment},\n\tpages = {2608--2617},\n\tfile = {IEEE Xplore Full Text PDF:C\\:\\\\Users\\\\4070tisuper\\\\Zotero\\\\storage\\\\SYCT44KE\\\\Aseeri and Interrante - 2021 - The Influence of Avatar Representation on Interper.pdf:application/pdf},\n}", 1, "@article{aseeri_influence_2021-1,\n\ttitle = {The {Influence} of {Avatar} {Representation} on {Interpersonal} {Communication} in {Virtual} {Social} {Environments}},\n\tvolume = {27},\n\tissn = {1941-0506},\n\tdoi = {10.1109/TVCG.2021.3067783},\n\tabstract = {Current avatar representations used in immersive VR applications lack features that may be important for supporting natural behaviors and effective communication among individuals. This study investigates the impact of the visual and nonverbal cues afforded by three different types of avatar representations in the context of several cooperative tasks. The avatar types we compared are No\\_Avatar (HMD and controllers only), Scanned\\_Avatar (wearing an HMD), and Heal\\_Avatar (video-see-through). The subjective and objective measures we used to assess the quality of interpersonal communication include surveys of social presence, interpersonal trust, communication satisfaction, and attention to behavioral cues, plus two behavioral measures: duration of mutual gaze and number of unique words spoken. We found that participants reported higher levels of trustworthiness in the Real\\_Avatar condition compared to the Scanned\\_Avatar and No\\_Avatar conditions. They also reported a greater level of attentional focus on facial expressions compared to the No\\_Avatar condition and spent more extended time, for some tasks, attempting to engage in mutual gaze behavior compared to the Scanned\\_Avatar and No\\_Avatar conditions. In both the Heal\\_Avatar and Scanned\\_Avatar conditions, participants reported higher levels of co-presence compared with the No\\_Avatar condition. In the Scanned\\_Avatar condition, compared with the Heal\\_Avatar and No\\_Avatar conditions, participants reported higher levels of attention to body posture. Overall, our exit survey revealed that a majority of participants (66.67\\%) reported a preference for the Real\\_Avatar, compared with 25.00\\% for the Scanned\\_Avatar and 8.33\\% for the No\\_Avatar, These findings provide novel insight into how a user's experience in a social VR scenario is affected by the type of avatar representation provided.},\n\tnumber = {5},\n\tjournal = {IEEE Transactions on Visualization and Computer Graphics},\n\tauthor = {Aseeri, Sahar and Interrante, Victoria},\n\tmonth = may,\n\tyear = {2021},\n\tnote = {Conference Name: IEEE Transactions on Visualization and Computer Graphics},\n\tkeywords = {Task analysis, trust, Avatars, Three-dimensional displays, Virtual environments, Atmospheric measurements, behavioral cues, communication satisfaction, interpersonal communication, Particle measurements, Resists, social presence, virtual environment},\n\tpages = {2608--2617},\n\tfile = {IEEE Xplore Abstract Record:C\\:\\\\Users\\\\4070tisuper\\\\Zotero\\\\storage\\\\QBS4677X\\\\9382845.html:text/html},\n}", True),
