    ('2608-04947', 1, '@article{Wyn73,\n\tdoi = {10.1109/tit.1973.1055108},\n\tyear = 1973,\n\tmonth = {nov},\n\tpublisher = {Institute of Electrical and Electronics Engineers ({IEEE})},\n\tvolume = {19},\n\tnumber = {6},\n\tpages = {772--777},\n\tauthor = {A. Wyner},\n\ttitle = {A theorem on the entropy of certain binary sequences and applications--{II}},\n\tjournal = {{IEEE} Transactions on Information Theory}\n}', 1, '@article{WZ73,\n\tdoi = {10.1109/tit.1973.1055107},\n\tyear = 1973,\n\tmonth = {nov},\n\tpublisher = {Institute of Electrical and Electronics Engineers ({IEEE})},\n\tvolume = {19},\n\tnumber = {6},\n\tpages = {769--772},\n\tauthor = {A. Wyner and J. Ziv},\n\ttitle = {A theorem on the entropy of certain binary sequences and applications--I},\n\tjournal = {{IEEE} Transactions on Information Theory}\n}', False),
    ('2608-08113', 1, '@article{zhang2019root,\n  title={Root Mean Square Layer Normalization},\n  author={Zhang, Biao and Sennrich, Rico},\n  journal={Advances in Neural Information Processing Systems},\n  volume={32},\n  year={2019}\n}', 1, '@misc{zhang2019rootmeansquarelayer,\n      title={Root Mean Square Layer Normalization}, \n      author={Biao Zhang and Rico Sennrich},\n      year={2019},\n      eprint={1910.07467},\n      archivePrefix={arXiv},\n      primaryClass={cs.LG},\n      url={https://arxiv.org/abs/1910.07467}, \n}', True),
    ('2608-08418', 1, '@article{He2009,\n\tAuthor = {Haibo He and Garcia, E.A.},\n\tDate-Added = {2019-01-10 23:20:22 +0000},\n\tDate-Modified = {2019-01-10 23:20:22 +0000},\n\tJournal = {IEEE Transactions on Knowledge and Data Engineering},\n\tMonth = {Sept},\n\tNumber = {9},\n\tPages = {1263-1284},\n\tTitle = {Learning from Imbalanced Data},\n\tVolume = {21},\n\tYear = {2009}}', 1, '@article{imbalance_IEEE,\n\tAuthor = {Haibo He and Garcia, E.A.},\n\tDate-Added = {2019-01-10 23:20:22 +0000},\n\tDate-Modified = {2019-01-10 23:20:22 +0000},\n\tJournal = {IEEE Transactions on Knowledge and Data Engineering},\n\tMonth = {Sept},\n\tNumber = {9},\n\tPages = {1263-1284},\n\tTitle = {Learning from Imbalanced Data},\n\tVolume = {21},\n\tYear = {2009}}', True),
    ('2608-07811', 1, '@misc{augenbraunDirectLaserCooling2023,\n  title = {Direct {{Laser Cooling}} of {{Polyatomic Molecules}}},\n  author = {Augenbraun, Benjamin L. and Anderegg, Loic and Hallas, Christian and Lasner, Zack D. and Vilas, Nathaniel B. and Doyle, John M.},\n  year = 2023,\n  month = feb,\n  eprint = {2302.10161},\n  abstract = {Over the past decade, tremendous progress has been made to extend the tools of laser cooling and trapping to molecules. Those same tools have recently been applied to polyatomic molecules (molecules containing three or more atoms). In this review, we discuss the scientific drive to bring larger molecules to ultralow temperatures, the features of molecular structure that provide the most promising molecules for this pursuit, and some technical aspects of how lasers can be used to control the motion and quantum states of polyatomic molecules. We also present opportunities for and challenges to the use of polyatomic molecules for science and technology.},\n  archiveprefix = {arXiv},\n  file = {/Users/arianjadbabaie/Zotero/storage/IRB45AWC/arxiv_2302.10161.pdf}\n}', 1, "@phdthesis{AugenbraunMethods2021,\n  title = {Methods for {{Direct Laser Cooling}} of {{Polyatomic Molecules}}},\n  author = {Augenbraun, Benjamin L},\n  year = 2021,\n  abstract = {Molecules controlled at the single-quantum-state level offer wide-ranging applications spanning many of the frontiers of modern physics. Within the past decade, simple diatomic molecules have been brought under full quantum control both via assembly from pre-cooled atoms and by direct laser cooling. Polyatomic molecules1 have attracted focus as novel quantum resources providing distinct advantages (and challenges) compared to both atoms and diatomic molecules. For example, nearly all polyatomic molecules have long-lived states that can be fully polarized at low applied electric fields. These and other features generic to polyatomic molecules can be applied to quantum simulation, quantum chemistry, and tests of fundamental physics beyond the Standard Model. While these structural features of polyatomic molecules are highly promising for applications, they complicate the process of bringing molecules under full quantum control. In this thesis, we describe a series of experimental and theoretical advances toward the production of ultracold complex polyatomic molecules. We demonstrate the first laser cooling of the polyatomic radical ytterbium monohydroxide (YbOH), a promising candidate to search for particles and interactions beyond the Standard Model of particle physics. We develop a novel deceleration technique (``Zeeman-Sisyphus deceleration'') capable of slowing molecular beams to trappable velocities while scattering fewer than 10 optical photons. This deceleration method is demonstrated using CaOH molecules, a lighter analog of YbOH. In order to determine a viable pathway to full three-dimensional cooling and trapping of YbOH, we develop a spectroscopic technique to measure vibrational branching ratios with relative intensity sensitivity around 1 part in 1Molecules that contain three or more atoms.},\n  langid = {english},\n  school = {Harvard},\n  file = {/Users/arianjadbabaie/Zotero/storage/K3TER4MQ/Augenbraun - Methods for Direct Laser Cooling of Polyatomic Mol.pdf}\n}", False),
